import React from "react";
import { GLYPHS, HEIGHT, UPM } from "./alnstStrokes.js";

// Hero line drawn along the lines of its ALNST glyphs (owner, 2026-10-13). Every glyph outline is revealed through
// a mask whose strokes run along the glyph's centre lines; all lines of all glyphs start together and finish
// together, and the glyph dots pop in once the lines are drawn. The geometry comes from alnstStrokes.js, generated by
// ui-v2/scripts/gen_alnst_strokes.py. landingEngine.js starts the drawing by setting data-assemble="on" on the line
// and settles it with "done"; landing.css holds the timing. The readable text stays a single visually hidden copy.

const MASK_WIDTH = 1.9; // × stroke thickness: covers the stroke from its centre line, ends and corners included

function contourPath(c) {
  let d = `M${c[0]} ${c[1]}`;
  for (let i = 2; i < c.length;) {
    if (c[i] === 0) {
      d += `L${c[i + 1]} ${c[i + 2]}`;
      i += 3;
    } else {
      d += `Q${c[i + 1]} ${c[i + 2]} ${c[i + 3]} ${c[i + 4]}`;
      i += 5;
    }
  }
  return d + "Z";
}

const linePath = (s) => {
  let d = `M${s[0]} ${s[1]}`;
  for (let i = 2; i < s.length; i += 2) d += `L${s[i]} ${s[i + 1]}`;
  return d;
};

export default function AssembleText({ text, tracking = 0 }) {
  const uid = React.useId().replace(/:/g, "");
  const chars = Array.from(text.toUpperCase());
  const gap = tracking * UPM;
  let x = 0;
  const placed = [];
  chars.forEach((ch, i) => {
    const g = GLYPHS[ch] || GLYPHS["?"];
    placed.push({ g, x, i });
    x += g.a + (i < chars.length - 1 ? gap : 0);
  });
  const width = Math.max(1, x);
  return (
    <>
      <span className="dgl-sr">{text}</span>
      <svg
        className="dgl-draw"
        aria-hidden="true"
        viewBox={`0 0 ${width} ${HEIGHT}`}
        style={{ width: `${width / UPM}em`, height: `${HEIGHT / UPM}em` }}
      >
        {placed.map(({ g, x: gx, i }) => {
          if (!g.c.length) return null;
          const id = `${uid}g${i}`;
          const body = g.c.filter((_, k) => !g.d.includes(k)).map(contourPath).join("");
          return (
            <g key={i} transform={`translate(${gx} 0)`}>
              {body && !g.s.length && <path d={body} fill="currentColor" />}
              {body && g.s.length > 0 && (
                <>
                  <mask id={id} maskUnits="userSpaceOnUse" x={-g.a} y={-HEIGHT} width={g.a * 3} height={HEIGHT * 3}>
                    {g.s.map((s, k) => (
                      <path
                        key={k}
                        className="dgl-stroke"
                        d={linePath(s)}
                        pathLength="1"
                        fill="none"
                        stroke="#fff"
                        strokeWidth={g.w * MASK_WIDTH}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    ))}
                  </mask>
                  <path d={body} mask={`url(#${id})`} fill="currentColor" />
                </>
              )}
              {g.d.map((k) => (
                <path key={`d${k}`} className="dgl-dotp" d={contourPath(g.c[k])} fill="currentColor" />
              ))}
            </g>
          );
        })}
      </svg>
    </>
  );
}
